/**
 * Hands a project to a new lead, or clears it with `leadId: null`. It is its
 * own operation rather than a `updateProject` field so it can be gated by
 * `project:change_lead`. A new lead must be an active member whose own role
 * lets them edit the project; every check runs before the write.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const member = await memberRepo.findMember(input.orgId, input.leadId);
    if (member?.status !== "active") {
      throw new NotFoundError("Member", input.leadId);
    }
    assertCan(
      { userId: input.leadId, orgId: input.orgId, role: member.role },
      "project:update",
      projectResource({ ...project, leadId: input.leadId }),
    );
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}

